# Writes src/scenes.json for "The Antifragile Man", from the user's script, read word for word except: the slurs
# "goycattle"/"goyifying" are not voiced, the claim that vaccines are poison is left out, "makes you gay" becomes
# "makes you weak", and "retardmaxx it" becomes "just send it". Made like "Live For Yourself": paintings, Rise Above
# captions, dark music. Per sentence: th = picture themes (src/images.json), big = the key word (red = huge red
# capitals), gap = silence after.
import json
S = []
def s(text, th, big=None, red=False, gap=0.8):
    S.append(dict(id=f"s{len([x for x in S if 'text' in x]) + 1:03d}", text=text, th=th if isinstance(th, list) else [th], big=big, red=red, gap=gap))
def ch(num, title, dur=4.4): S.append(dict(id=f"ch{sum(1 for x in S if 'card' in x) + 1}", card="chapter", num=num, title=title, len=dur))

# ---- opening
s("There's a kind of man who'll never make it.", ["lonely"], big="never", red=True, gap=1.0)
