s("But not you and me.", ["alpine"], big="not", gap=1.0)
s("Imagine the life that awaits you after this shift in perspective.", ["alpine", "sunrise"], big="Imagine")
s("Watching the sunrise on an adventure in Switzerland.", ["sunrise", "alpine"], big="sunrise")
